<?php

use PHPUnit\Framework\TestCase;

class ConfigTest extends TestCase
{
    private string $dir;
    private string $file;

    protected function setUp(): void
    {
        $this->dir  = TEST_FIXTURES_DIR . '/config_' . uniqid();
        $this->file = $this->dir . '/config.php';
        mkdir($this->dir, 0755, true);

        file_put_contents($this->file, <<<'PHP'
<?php
// Generated by setup.php

return [

    'base_url'            => 'https://example.com/badal',

    'podcast_title'       => 'Mon Podcast',
    'podcast_description' => 'Bienvenue sur mon podcast.',
    'author'              => '',

    'admin_username'      => 'admin',
    'admin_password_hash' => '$2y$12$abcdefghijklmnopqrstuuvwxyzABCDEFGHIJKLMNOPQRSTUVWXY',

    'content_dir' => dirname(__DIR__) . '/content',
    'audio_dir'   => dirname(__DIR__) . '/audio',

];

PHP);
    }

    protected function tearDown(): void
    {
        foreach (glob($this->dir . '/{,.}*', GLOB_BRACE) as $f) {
            if (is_file($f)) unlink($f);
        }
        rmdir($this->dir);
    }

    private function load(): array
    {
        return require $this->file;
    }

    // =========================================================================
    //  Round-trip of hostile values
    // =========================================================================

    /**
     * @dataProvider trickyValues
     */
    public function testValueRoundTripsExactly(string $value): void
    {
        $this->assertTrue(Config::set($this->file, 'podcast_title', $value));
        $this->assertSame($value, $this->load()['podcast_title']);
    }

    public function trickyValues(): array
    {
        return [
            'apostrophe'          => ["L'heure du crime"],
            'backslash'           => ['AC\\DC'],
            'trailing backslash'  => ['Back\\'],
            'backreference $1'    => ['Price $1 off'],
            'backreference \\1'   => ['Group \\1 ref'],
            'newline'             => ["Line 1\nLine 2"],
            'unicode'             => ['Épisode — 🎙️'],
            'empty'               => [''],
        ];
    }

    public function testBcryptHashIsStoredIntact(): void
    {
        $hash = password_hash('secret123', PASSWORD_BCRYPT, ['cost' => 4]);

        $this->assertTrue(Config::set($this->file, 'admin_password_hash', $hash));

        $stored = $this->load()['admin_password_hash'];
        $this->assertSame($hash, $stored);
        $this->assertTrue(password_verify('secret123', $stored));
    }

    public function testInjectionAttemptStaysAString(): void
    {
        $payload = "Pwn\\', strtoupper(PHP_OS), //";

        $this->assertTrue(Config::set($this->file, 'podcast_title', $payload));

        $config = $this->load();
        $this->assertSame($payload, $config['podcast_title']);
        $this->assertNotContains(strtoupper(PHP_OS), $config);
    }

    // =========================================================================
    //  File structure
    // =========================================================================

    public function testOtherKeysAndExpressionsArePreserved(): void
    {
        Config::set($this->file, 'author', 'Chris');
        $config = $this->load();

        $this->assertSame('Chris', $config['author']);
        $this->assertSame('Mon Podcast', $config['podcast_title']);
        $this->assertStringEndsWith('/content', $config['content_dir']);
        $this->assertStringContainsString("dirname(__DIR__) . '/content'", file_get_contents($this->file));
    }

    public function testValueContainingEscapedQuoteIsReplacedAgain(): void
    {
        Config::set($this->file, 'podcast_title', "L'heure du crime");
        Config::set($this->file, 'podcast_title', 'Renamed');

        $this->assertSame('Renamed', $this->load()['podcast_title']);
        $this->assertSame(1, substr_count(file_get_contents($this->file), "'podcast_title'"));
    }

    public function testMissingKeyIsAppended(): void
    {
        $this->assertTrue(Config::set($this->file, 'redirect_feed_url', 'https://new.example.com/rss.xml'));
        $this->assertSame('https://new.example.com/rss.xml', $this->load()['redirect_feed_url']);
    }

    public function testSetManyWritesAllKeys(): void
    {
        $this->assertTrue(Config::setMany($this->file, [
            'podcast_title' => 'A $1 B',
            'author'        => 'C\\D',
            'email'         => 'me@example.com',
        ]));

        $config = $this->load();
        $this->assertSame('A $1 B', $config['podcast_title']);
        $this->assertSame('C\\D', $config['author']);
        $this->assertSame('me@example.com', $config['email']);
    }

    // =========================================================================
    //  Failure modes
    // =========================================================================

    public function testInvalidKeyIsRejectedAndFileUntouched(): void
    {
        $before = file_get_contents($this->file);

        $this->assertFalse(Config::set($this->file, "bad'key", 'x'));
        $this->assertSame($before, file_get_contents($this->file));
    }

    public function testUnparseableResultIsNotWritten(): void
    {
        // Simulate a config that is already broken: the write must refuse
        file_put_contents($this->file, "<?php\nreturn [\n    'podcast_title' => 'x',\n    'author' => 'a' 'b',\n];\n");
        $before = file_get_contents($this->file);

        $this->assertFalse(Config::set($this->file, 'podcast_title', 'y'));
        $this->assertSame($before, file_get_contents($this->file));
    }

    public function testMissingFileReturnsFalse(): void
    {
        $this->assertFalse(Config::set($this->dir . '/nope.php', 'podcast_title', 'x'));
    }
}
